mapper.select:


    inner join sys_user u on u.user_name = tcheckdelivery.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tcheckdelivery.del_flag = '0'
     and tcheckdelivery.check_type = #{checkType}
     and tcheckdelivery.material_id = #{materialId}
     and tcheckdelivery.area_id = #{areaId}
     and tcheckdelivery.reservoir_id = #{reservoirId}
     and tcheckdelivery.auditor = #{auditor}
     and tcheckdelivery.status = #{status}


${params.dataScope}

select t1.id, t1.dept_id, t1.dept_name, t1.area_id, t1.reservoir_id, t1.material_id, t1.check_type, t1.create_by, t1.create_time, t1.start_time, t1.end_time, t1.random_num, t1.tray_type, t2.available_count, t2.library_count, t1.batch_code, t1.location_id, t1.status from t_check_delivery t1 left join t_stock_main t2 ON t1.material_id = t2.material_id left join t_material t3 on t3.id = t1.material_id
inner join sys_user u on u.user_name = t1.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
where t1.del_flag = '0' and t3.name like concat('%', #{materialName}, '%') and t1.status = #{status} and t1.check_type = #{checkType} and t1.dept_id = #{deptId} and t1.area_id = #{areaId} and t1.reservoir_id = #{reservoirId} and t1.id in
#{id}
and t1.material_id in
#{materialId}
and t1.create_time between date_format(#{startTime},'%y%m%d') and date_format(#{endTime},'%y%m%d')
and t1.tray_type = #{trayType}
${params.dataScope} order by t1.create_time desc

select cd.id,cd.plan_name,cd.check_source,cd.reservoir_id ,r.`name` as reservoir_name,cd.material_id,m.name as material_name,m.code as material_code, -- ifnull((SELECT sum(rfid_count) from t_material_detail where material_id=cd.material_id and del_flag='0'),0) as library_count, ifnull(( SELECT sum(rfid_count) from t_material_detail s left join t_material m on m.id=s.material_id left join t_location l on l.id=s.location_id left join t_tray tray on s.tray_id = tray.id where material_id=cd.material_id and s.del_flag = 0 and s.rfid_count != 0 and tray.tray_category=#{trayType} and l.location_type != '1' ),0) as library_count, cd.task_status, cd.status,cd.create_time,cd.create_by,tu.name as unit_name from t_check_delivery cd left join t_material m on cd.material_id = m.id LEFT JOIN t_reservoir r on cd.reservoir_id=r.id left join t_unit tu on m.unit_id = tu.id
cd.del_flag = '0' and cd.plan_name= #{planName} and cd.tray_type= #{trayType} and m.name = #{materialName} and cd.check_type = #{checkType}
order by cd.plan_name,cd.status ,cd.create_time DESC
